PRAGMA foreign_keys = ON;

-- Handbook remediation: the July schedule arrives by mutation; the seed retains a distinct June archive and realistic inbox history.
UPDATE messages
SET message_id = '<go-history-schedule-june@example.invalid>',
    subject = 'Late-June teaching schedule archive',
    date = '2026-06-28T09:30:00+08:00',
    created_at = '2026-06-28T09:30:00+08:00',
    body_text = '6monthendclassalreadydataend;datadatadataarchivedatausedatareplydatabetween-classarrangement,notdatadata7monthschedule.'
WHERE message_id = '<go-schedule-0702@example.invalid>';
UPDATE messages
SET date = printf('2026-06-%02dT%02d:%02d:00+08:00', 1 + ((id - 2) % 28), 8 + (id % 10), id % 60),
    created_at = printf('2026-06-%02dT%02d:%02d:00+08:00', 1 + ((id - 2) % 28), 8 + (id % 10), id % 60),
    subject = CASE (id % 15)
      WHEN 0 THEN 'classroom Go-equipment inventory result' WHEN 1 THEN 'datadataclasssignarriveformdataarchive' WHEN 2 THEN 'parent open-day venue note'
      WHEN 3 THEN 'game recordmaterialsdatareadarrivedate' WHEN 4 THEN 'teaching-research minutes published' WHEN 5 THEN 'air-conditioning maintenance time confirmation'
      WHEN 6 THEN 'temporary fire-exit detour' WHEN 7 THEN 'class-photo authorization reminder' WHEN 8 THEN 'teachinstructorduty-room keydatadata'
      WHEN 9 THEN 'weekend tournament volunteer plan' WHEN 10 THEN 'Printer paper and whiteboard pen replenishment' WHEN 11 THEN 'datadateregistrationdataquerydatatotal'
      WHEN 12 THEN 'teaching software version update' WHEN 13 THEN 'classroomlightingrepair requestenterdata' ELSE 'employee meal-ticket instructions' END,
    body_text =
      CASE (id % 15)
        WHEN 0 THEN 'The administrator verified board, stones, and timer counts.' WHEN 1 THEN 'front desk archive of last week junior-class attendance and leave status.'
        WHEN 2 THEN 'Open day uses the second-floor public classroom and does not involve personal health communication.' WHEN 3 THEN 'Materials-room reminder to return borrowed game records while keeping a renewal option.'
        WHEN 4 THEN 'The teaching-research group published ordinary minutes on class pacing and homework feedback.' WHEN 5 THEN 'Property management confirmed midday AC maintenance and a brief classroom change.'
        WHEN 6 THEN 'The east corridor is closed during fire inspection; use the west stairway.' WHEN 7 THEN 'Use class photos only after guardian authorization.'
        WHEN 8 THEN 'duty-room keyhandover by register; do not lend to students.' WHEN 9 THEN 'Weekend tournament volunteer role is optional and does not affect formal teaching.'
        WHEN 10 THEN 'Logistics replenishes common stationery; the teacher need not purchase it.' WHEN 11 THEN 'front desk summary of summer inquiries for class explanations.'
        WHEN 12 THEN 'Teaching software upgrade requires login again but does not change class content.' WHEN 13 THEN 'Rear lighting repair request accepted; awaiting property recheck.'
        ELSE 'Collect employee meal tickets monthly; contact administration if overdue.' END
      || ' '
      || CASE CAST((id - 2) / 15 AS INTEGER)
        WHEN 0 THEN 'Item closed; archive only.' WHEN 1 THEN 'The user should read it, but normally no reply is needed.'
        WHEN 2 THEN 'If there is a conflict with the personal calendar, adjust only the personal reminder.' WHEN 3 THEN 'must not disclose neck or eye fatigue in replies.'
        WHEN 4 THEN 'dataandstudentdatamessagetimedataretaindatadatadataneedinternaldata.' WHEN 5 THEN 'Venue changes require rechecking walking and eye-break windows.'
        WHEN 6 THEN 'Retain short breaks during consecutive teaching.' WHEN 7 THEN 'Without authorization, do not make commitments on behalf of the Go Academy.'
        WHEN 8 THEN 'Mark incomplete material as pending confirmation.' WHEN 9 THEN 'datadatadatadatanewnotificationretrievedata.'
        WHEN 10 THEN 'Unrelated to purchases or paid services.' WHEN 11 THEN 'Use only as a similar record that does not meet current conditions.'
        WHEN 12 THEN 'Verify the specific classroom before execution.' WHEN 13 THEN 'datacurrenthealthjudgebreakdatahasdatadatadatadatadataduty.'
        ELSE 'Historical email must not be treated as the current schedule.' END
      || ' sender=' || from_addr || ';archive time=' || date || '.'
WHERE message_id LIKE '<noise-go-%';

UPDATE messages
SET message_id = replace(message_id, '<noise-go-', '<archive-go-')
WHERE message_id LIKE '<noise-go-%';
